import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, computed, contentChild, ElementRef, inject, input, model, NgModule, numberAttribute, output, signal, TemplateRef, viewChild, ViewEncapsulation, ViewRef } from '@angular/core';
import { MotionEvent, MotionOptions } from '@primeuix/motion';
import { absolutePosition, addStyle, appendChild, find, findSingle, focus, isTouchDevice, uuid } from '@primeuix/utils';
import { MenuItem, OverlayService, SharedModule } from 'primeng/api';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { ConnectedOverlayScrollHandler } from 'primeng/dom';
import { MotionModule } from 'primeng/motion';
import { TooltipModule } from 'primeng/tooltip';
import { VoidListener } from 'primeng/ts-helpers';
import { MenuExpandedKeys, MenuItemTemplateContext, MenuPassThrough, MenuSubmenuHeaderTemplateContext } from 'primeng/types/menu';
import type { AppendTo, CSSProperties } from 'primeng/types/shared';
import { ZIndexUtils } from 'primeng/utils';
import { MenuItemContent, SafeHtmlPipe } from './menu-item-content';
import { MENU_INSTANCE } from './menu-token';
import { MenuStyle } from './style/menustyle';

/**
 * Menu is a navigation / command component that supports dynamic and static positioning.
 * @group Components
 */
@Component({
    selector: 'p-menu',
    standalone: true,
    imports: [NgTemplateOutlet, MenuItemContent, TooltipModule, SharedModule, SafeHtmlPipe, BindModule, MotionModule],
    template: `
        @if (!popup() || overlayVisible()) {
            <div
                #container
                [class]="cn(cx('root'), styleClass())"
                [style]="sx('root')"
                (click)="onOverlayClick($event)"
                [attr.id]="$id()"
                [pBind]="ptm('root')"
                [attr.data-p]="dataP()"
                [pMotion]="visible() || !popup()"
                [pMotionName]="'p-anchored-overlay'"
                [pMotionAppear]="!!popup()"
                [pMotionDisabled]="!popup()"
                [pMotionOptions]="computedMotionOptions()"
                (pMotionOnBeforeEnter)="onOverlayBeforeEnter($event)"
                (pMotionOnAfterLeave)="onOverlayAfterLeave()"
            >
                @if (startTemplate()) {
                    <div [class]="cx('start')" [pBind]="ptm('start')" [attr.data-pc-section]="'start'">
                        <ng-container *ngTemplateOutlet="startTemplate()"></ng-container>
                    </div>
                }
                <ul
                    #list
                    [class]="cx('list')"
                    [pBind]="ptm('list')"
                    role="menu"
                    [attr.id]="$id() + '_list'"
                    [attr.tabindex]="getTabIndexValue()"
                    [attr.data-pc-section]="'menu'"
                    [attr.aria-activedescendant]="activedescendant()"
                    [attr.aria-label]="ariaLabel()"
                    [attr.aria-labelledBy]="ariaLabelledBy()"
                    (focus)="onListFocus($event)"
                    (blur)="onListBlur($event)"
                    (keydown)="onListKeyDown($event)"
                >
                    <ng-container *ngTemplateOutlet="recursiveItems; context: { $implicit: model(), depth: 0, parentId: $id() }"></ng-container>
                    <ng-template #recursiveItems let-items let-depth="depth" let-parentId="parentId">
                        @for (item of items; track item.id ?? i; let i = $index) {
                            @if (isSeparatorVisible(item)) {
                                <li [class]="cx('separator')" [pBind]="ptm('separator')" role="separator" [attr.data-pc-section]="'separator'"></li>
                            }
                            @if (!item.separator && isVisible(item)) {
                                @if (item.items?.length && !isSubmenuToggleable(item, depth)) {
                                    <li
                                        [class]="cx('submenuLabel')"
                                        [attr.data-depth]="depth || null"
                                        [pBind]="ptm('submenuLabel')"
                                        [attr.data-automationid]="item.automationId"
                                        pTooltip
                                        [tooltipOptions]="item.tooltipOptions"
                                        [pTooltipUnstyled]="unstyled()"
                                        role="none"
                                        [attr.id]="menuitemId(item, parentId, i)"
                                        [attr.data-pc-section]="'submenulabel'"
                                    >
                                        @if (!submenuHeaderTemplate()) {
                                            @if (item.escape !== false) {
                                                <span>{{ item.label }}</span>
                                            } @else {
                                                <span [innerHTML]="item.label | safeHtml"></span>
                                            }
                                        }
                                        <ng-container *ngTemplateOutlet="submenuHeaderTemplate(); context: { $implicit: item }"></ng-container>
                                    </li>
                                    <ng-container *ngTemplateOutlet="recursiveItems; context: { $implicit: item.items, depth: depth + 1, parentId: menuitemId(item, parentId, i) }"></ng-container>
                                } @else {
                                    <li
                                        [class]="cn(cx('item', { item, id: menuitemId(item, parentId, i), toggleable: !!item.items?.length && isSubmenuToggleable(item, depth) }), item?.styleClass)"
                                        [pBind]="ptm('item')"
                                        [pMenuItemContent]="item"
                                        [itemTemplate]="itemTemplate()"
                                        [idx]="i"
                                        [menuitemId]="menuitemId(item, parentId, i)"
                                        [toggleable]="!!item.items?.length && isSubmenuToggleable(item, depth)"
                                        [expanded]="isSubmenuExpanded(item, depth, menuitemId(item, parentId, i))"
                                        [depth]="depth"
                                        [submenuIconTemplate]="submenuIconTemplate()"
                                        [style]="item.style"
                                        (onMenuItemClick)="itemClick($event, menuitemId(item, parentId, i))"
                                        pTooltip
                                        [tooltipOptions]="item.tooltipOptions"
                                        [pTooltipUnstyled]="unstyled()"
                                        [unstyled]="unstyled()"
                                        role="menuitem"
                                        [attr.aria-label]="label(item.label)"
                                        [attr.aria-haspopup]="!!item.items?.length && isSubmenuToggleable(item, depth) ? 'true' : null"
                                        [attr.aria-expanded]="!!item.items?.length && isSubmenuToggleable(item, depth) ? isSubmenuExpanded(item, depth, menuitemId(item, parentId, i)) : null"
                                        [attr.data-focused]="isItemFocused(menuitemId(item, parentId, i))"
                                        [attr.data-disabled]="disabled(item.disabled)"
                                        [attr.data-toggleable]="(!!item.items?.length && isSubmenuToggleable(item, depth)) || null"
                                        [attr.data-depth]="!!item.items?.length && isSubmenuToggleable(item, depth) ? depth : null"
                                        [attr.aria-disabled]="disabled(item.disabled)"
                                        [attr.id]="menuitemId(item, parentId, i)"
                                        [attr.data-pc-section]="'item'"
                                        (click)="onItemLiClick($event, item, menuitemId(item, parentId, i), depth)"
                                        (mousedown)="onItemLiMousedown($event, item, depth)"
                                    >
                                        @if (!!item.items?.length && isSubmenuToggleable(item, depth) && isSubmenuExpanded(item, depth, menuitemId(item, parentId, i))) {
                                            <ul [class]="cx('submenuList')" [pBind]="ptm('submenuList')" role="menu">
                                                <ng-container *ngTemplateOutlet="recursiveItems; context: { $implicit: item.items, depth: depth + 1, parentId: menuitemId(item, parentId, i) }"></ng-container>
                                            </ul>
                                        }
                                    </li>
                                }
                            }
                        }
                    </ng-template>
                </ul>
                @if (endTemplate()) {
                    <div [class]="cx('end')" [pBind]="ptm('end')" [attr.data-pc-section]="'end'">
                        <ng-container *ngTemplateOutlet="endTemplate()"></ng-container>
                    </div>
                }
            </div>
        }
    `,

    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [MenuStyle, { provide: MENU_INSTANCE, useExisting: Menu }, { provide: PARENT_INSTANCE, useExisting: Menu }],
    hostDirectives: [Bind]
})
export class Menu extends BaseComponent<MenuPassThrough> {
    componentName = 'Menu';

    /**
     * An array of menuitems.
     * @group Props
     */
    model = input<MenuItem[]>();
    /**
     * Defines if menu would displayed as a popup.
     * @group Props
     */
    popup = input(false, { transform: booleanAttribute });
    /**
     * Inline style of the component.
     * @group Props
     */
    style = input<CSSProperties>();
    /**
     * Style class of the component.
     * @group Props
     */
    styleClass = input<string>();
    /**
     * Whether to automatically manage layering.
     * @group Props
     */
    autoZIndex = input(true, { transform: booleanAttribute });
    /**
     * Base zIndex value to use in layering.
     * @group Props
     */
    baseZIndex = input(0, { transform: numberAttribute });
    /**
     * Defines a string value that labels an interactive element.
     * @group Props
     */
    ariaLabel = input<string>();
    /**
     * Identifier of the underlying input element.
     * @group Props
     */
    ariaLabelledBy = input<string>();
    /**
     * Current id state as a string.
     * @group Props
     */
    id = input<string>();
    /**
     * Index of the element in tabbing order.
     * @group Props
     */
    tabindex = input(0, { transform: numberAttribute });
    /**
     * Target element to attach the overlay, valid values are "body" or a local ng-template variable of another element (note: use binding with brackets for template variables, e.g. [appendTo]="mydiv" for a div element having #mydiv as variable name).
     * @defaultValue 'self'
     * @group Props
     */
    appendTo = input<AppendTo>(undefined);
    /**
     * The motion options.
     * @group Props
     */
    motionOptions = input<MotionOptions | undefined>(undefined);
    /**
     * When provided, switches the component to controlled mode; each key is the DOM id of a toggleable submenu header and the value its expansion flag.
     * Use two-way binding with `[(expandedKeys)]`.
     * @group Props
     */
    expandedKeys = model<MenuExpandedKeys>();

    /**
     * Callback to invoke when overlay menu is shown.
     * @group Emits
     */
    onShow = output<object>();
    /**
     * Callback to invoke when overlay menu is hidden.
     * @group Emits
     */
    onHide = output<object>();
    /**
     * Callback to invoke when the list loses focus.
     * @param {Event} event - blur event.
     * @group Emits
     */
    onBlur = output<Event>();
    /**
     * Callback to invoke when the list receives focus.
     * @param {Event} event - focus event.
     * @group Emits
     */
    onFocus = output<Event>();

    /**
     * Defines template option for start.
     * @group Templates
     */
    startTemplate = contentChild<TemplateRef<void>>('start', { descendants: false });

    /**
     * Defines template option for end.
     * @group Templates
     */
    endTemplate = contentChild<TemplateRef<void>>('end', { descendants: false });

    /**
     * Custom item template.
     * @param {MenuItemTemplateContext} context - item context.
     * @see {@link MenuItemTemplateContext}
     * @group Templates
     */
    itemTemplate = contentChild<TemplateRef<MenuItemTemplateContext>>('item', { descendants: false });

    /**
     * Custom submenu header template.
     * @param {MenuSubmenuHeaderTemplateContext} context - submenu header context.
     * @see {@link MenuSubmenuHeaderTemplateContext}
     * @group Templates
     */
    submenuHeaderTemplate = contentChild<TemplateRef<MenuSubmenuHeaderTemplateContext>>('submenuheader', { descendants: false });

    /**
     * Custom submenu toggle icon template.
     * @param {MenuSubmenuHeaderTemplateContext} context - submenu header context.
     * @see {@link MenuSubmenuHeaderTemplateContext}
     * @group Templates
     */
    submenuIconTemplate = contentChild<TemplateRef<MenuSubmenuHeaderTemplateContext>>('submenuicon', { descendants: false });

    listViewChild = viewChild<ElementRef>('list');

    containerViewChild = viewChild<ElementRef>('container');

    private _internalId = uuid('pn_id_');

    $id = computed(() => this.id() || this._internalId);

    $appendTo = computed(() => this.appendTo() || this.config.overlayAppendTo());

    computedMotionOptions = computed<MotionOptions>(() => ({
        ...this.ptm('motion'),
        ...this.motionOptions()
    }));

    container: HTMLElement | undefined;

    scrollHandler: ConnectedOverlayScrollHandler | null | undefined;

    documentClickListener: VoidListener;

    documentResizeListener: VoidListener;

    preventDocumentDefault: boolean | undefined;

    target: HTMLElement | null = null;

    visible = signal(false);

    focusedOptionId = computed(() => (this.focusedOptionIndex() !== -1 ? this.focusedOptionIndex() : null));

    focusedOptionIndex = signal<string | number>(-1);

    selectedOptionIndex = signal<number>(-1);

    focused = signal(false);

    overlayVisible = signal(false);

    d_expandedKeys = signal<MenuExpandedKeys>({});

    currentExpandedKeys = computed(() => (this.expandedKeys() !== undefined ? this.expandedKeys()! : this.d_expandedKeys()));

    $pcMenu: Menu | undefined = inject(MENU_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    overlayService = inject(OverlayService);

    _componentStyle = inject(MenuStyle);

    bindDirectiveInstance = inject(Bind, { self: true });

    dataP = computed(() =>
        this.cn({
            popup: this.popup()
        })
    );

    activedescendant = computed(() => (this.focused() ? this.focusedOptionId() : undefined));

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptm('host'));
    }
    getPTOptions(key: string, item: MenuItem | undefined, index: number, id: string) {
        return this.ptm(key, {
            context: {
                item: item,
                index: index,
                focused: this.isItemFocused(id),
                disabled: this.disabled(item?.disabled)
            }
        });
    }
    /**
     * Toggles the visibility of the popup menu.
     * @param {Event} event - Browser event.
     * @group Method
     */
    public toggle(event: Event) {
        if (this.visible()) this.hide();
        else this.show(event);

        this.preventDocumentDefault = true;
    }

    /**
     * Displays the popup menu.
     * @param {Event} event - Browser event.
     * @group Method
     */
    public show(event: Event) {
        if (this.container && !this.overlayVisible()) {
            this.container = undefined;
        }

        this.target = event.currentTarget as HTMLElement | null;
        this.visible.set(true);
        this.preventDocumentDefault = true;
        this.overlayVisible.set(true);
    }

    onInit() {
        if (!this.popup()) {
            this.bindDocumentClickListener();
        }
    }

    getTabIndexValue(): string | null {
        const tabindexValue = this.tabindex();

        return tabindexValue !== undefined ? tabindexValue.toString() : null;
    }

    onOverlayBeforeEnter(event: MotionEvent) {
        this.container = event.element as HTMLElement;

        if (this.container) {
            addStyle(this.container, { position: 'absolute', top: '0' });
            this.appendOverlay();
            this.moveOnTop();

            if (this.$attrSelector) {
                this.container?.setAttribute(this.$attrSelector, '');
            }

            this.bindDocumentClickListener();
            this.bindDocumentResizeListener();
            this.bindScrollListener();
            absolutePosition(this.container!, this.target!);
            focus(this.listViewChild()?.nativeElement);
            this.onShow.emit({});
        }
    }

    onOverlayAfterLeave() {
        this.restoreOverlayAppend();
        this.onOverlayHide();
        this.overlayVisible.set(false);
        this.onHide.emit({});
    }

    appendOverlay() {
        if (this.$appendTo() && this.$appendTo() !== 'self') {
            if (this.$appendTo() === 'body') {
                appendChild(this.document.body, this.container!);
            } else {
                appendChild(this.$appendTo(), this.container!);
            }
        }
    }

    restoreOverlayAppend() {
        if (this.container && this.$appendTo() !== 'self') {
            appendChild(this.el.nativeElement, this.container);
        }
    }
    moveOnTop() {
        if (this.autoZIndex()) {
            ZIndexUtils.set('menu', this.container, this.baseZIndex() + this.config.zIndex.menu);
        }
    }

    /**
     * Hides the popup menu.
     * @group Method
     */
    public hide() {
        this.visible.set(false);
    }

    onWindowResize() {
        if (this.visible() && !isTouchDevice()) {
            this.hide();
        }
    }

    menuitemId(item: MenuItem, id: string, index?: string | number, childIndex?: string | number) {
        return item?.id ?? `${id}_${index}${childIndex !== undefined ? '_' + childIndex : ''}`;
    }

    isItemFocused(id: string | number | null) {
        return this.focusedOptionId() === id;
    }

    label(label: string | (() => string) | undefined) {
        return typeof label === 'function' ? label() : label;
    }

    disabled(disabled: boolean | (() => boolean) | undefined) {
        return typeof disabled === 'function' ? disabled() : typeof disabled === 'undefined' ? false : disabled;
    }

    isVisible(item: MenuItem) {
        return item.visible !== false;
    }

    isSeparatorVisible(item: MenuItem) {
        return item.separator && this.isVisible(item);
    }

    isItemVisible(item: MenuItem) {
        return !item.separator && this.isVisible(item);
    }

    isSubmenuSeparatorVisible(item: MenuItem, submenu: MenuItem) {
        return item.separator && (this.isVisible(item) || this.isVisible(submenu));
    }

    isSubmenuItemVisible(item: MenuItem, submenu: MenuItem) {
        return !item.separator && this.isVisible(item) && (item.visible !== undefined || this.isVisible(submenu));
    }

    onListFocus(event: Event) {
        if (!this.focused()) {
            this.focused.set(true);

            if (!this.popup() && !this.focusedOptionId()) {
                this.changeFocusedOptionIndex(0);
            }

            this.onFocus.emit(event);
        }
    }

    onListBlur(event: FocusEvent | MouseEvent) {
        if (this.focused()) {
            this.focused.set(false);
            this.changeFocusedOptionIndex(-1);
            this.selectedOptionIndex.set(-1);
            this.focusedOptionIndex.set(-1);
            this.onBlur.emit(event);
        }
    }

    onListKeyDown(event: KeyboardEvent) {
        switch (event.code) {
            case 'ArrowDown':
                this.onArrowDownKey(event);
                break;

            case 'ArrowUp':
                this.onArrowUpKey(event);
                break;

            case 'Home':
                this.onHomeKey(event);
                break;

            case 'End':
                this.onEndKey(event);
                break;

            case 'Enter':
                this.onEnterKey(event);
                break;

            case 'NumpadEnter':
                this.onEnterKey(event);
                break;

            case 'Space':
                this.onSpaceKey(event);
                break;

            case 'Escape':
            case 'Tab':
                if (this.popup()) {
                    if (this.target) {
                        focus(this.target);
                    }

                    this.hide();
                }

                if (this.overlayVisible()) {
                    this.hide();
                }

                break;

            default:
                break;
        }
    }

    onArrowDownKey(event: KeyboardEvent) {
        const optionIndex = this.findNextOptionIndex(this.focusedOptionIndex());

        this.changeFocusedOptionIndex(optionIndex);
        event.preventDefault();
    }

    onArrowUpKey(event: KeyboardEvent) {
        if (event.altKey && this.popup()) {
            if (this.target) {
                focus(this.target);
            }

            this.hide();
            event.preventDefault();
        } else {
            const optionIndex = this.findPrevOptionIndex(this.focusedOptionIndex());

            this.changeFocusedOptionIndex(optionIndex);
            event.preventDefault();
        }
    }

    onHomeKey(event: KeyboardEvent) {
        this.changeFocusedOptionIndex(0);
        event.preventDefault();
    }

    onEndKey(event: KeyboardEvent) {
        this.changeFocusedOptionIndex(find(this.containerViewChild()?.nativeElement, 'li[data-pc-section="item"][data-disabled="false"]').length - 1);
        event.preventDefault();
    }

    onEnterKey(event: KeyboardEvent) {
        event.preventDefault();

        const element = findSingle(this.listViewChild()?.nativeElement, `[id="${`${this.focusedOptionIndex()}`}"]`) as HTMLElement | null;

        if (!element) return;

        if (element.getAttribute('data-toggleable') === 'true') {
            const content = (findSingle(element, '[data-pc-section="itemcontent"]') || element) as HTMLElement;

            content.click();

            return;
        }

        const anchorElement = findSingle(element, 'a[data-pc-section="itemlink"]') as HTMLElement | null;
        const contentElement = findSingle(element, '[data-pc-section="itemcontent"]') as HTMLElement | null;

        if (this.popup() && this.target) {
            focus(this.target);
        }

        (anchorElement || contentElement || element).click();
    }

    onSpaceKey(event: KeyboardEvent) {
        this.onEnterKey(event);
    }

    findNextOptionIndex(index: string | number) {
        const links = find(this.containerViewChild()?.nativeElement, 'li[data-pc-section="item"][data-disabled="false"]');
        const matchedOptionIndex = [...links].findIndex((link) => link.id === index);

        return matchedOptionIndex > -1 ? matchedOptionIndex + 1 : 0;
    }

    findPrevOptionIndex(index: string | number) {
        const links = find(this.containerViewChild()?.nativeElement, 'li[data-pc-section="item"][data-disabled="false"]');
        const matchedOptionIndex = [...links].findIndex((link) => link.id === index);

        return matchedOptionIndex > -1 ? matchedOptionIndex - 1 : 0;
    }

    changeFocusedOptionIndex(index: number) {
        const links = find(this.containerViewChild()?.nativeElement, 'li[data-pc-section="item"][data-disabled="false"]');

        if (links.length > 0) {
            let order = index >= links.length ? links.length - 1 : index < 0 ? 0 : index;

            if (order > -1) {
                this.focusedOptionIndex.set(links[order].getAttribute('id') ?? -1);
            }
        }
    }

    itemClick(event: { originalEvent: Event; item: MenuItem }, id: string) {
        const { originalEvent, item } = event;

        if (!this.focused()) {
            this.focused.set(true);
            this.onFocus.emit(originalEvent);
        }

        if (item.disabled) {
            originalEvent.preventDefault();

            return;
        }

        if (!item.url && !item.routerLink) {
            originalEvent.preventDefault();
        }

        if (item.command) {
            item.command({
                originalEvent: originalEvent,
                item: item
            });
        }

        if (this.popup()) {
            this.hide();
        }

        if (!this.popup() && this.focusedOptionIndex() !== id) {
            this.focusedOptionIndex.set(id);
        }
    }

    onOverlayClick(event: Event) {
        if (this.popup()) {
            this.overlayService.add({
                originalEvent: event,
                target: this.el.nativeElement
            });
        }

        this.preventDocumentDefault = true;
    }

    bindDocumentClickListener() {
        if (!this.documentClickListener && isPlatformBrowser(this.platformId)) {
            const documentTarget = this.el ? this.el.nativeElement.ownerDocument : this.document;

            this.documentClickListener = this.renderer.listen(documentTarget, 'click', (event) => {
                const isOutsideContainer = this.containerViewChild()?.nativeElement && !this.containerViewChild()?.nativeElement.contains(event.target);
                const isOutsideTarget = !(this.target && (this.target === event.target || this.target.contains(event.target)));

                if (!this.popup() && isOutsideContainer && isOutsideTarget) {
                    this.onListBlur(event);
                }

                if (this.preventDocumentDefault && this.overlayVisible() && isOutsideContainer && isOutsideTarget) {
                    this.hide();
                    this.preventDocumentDefault = false;
                }
            });
        }
    }

    unbindDocumentClickListener() {
        if (this.documentClickListener) {
            this.documentClickListener();
            this.documentClickListener = null;
        }
    }

    bindDocumentResizeListener() {
        if (!this.documentResizeListener && isPlatformBrowser(this.platformId)) {
            const window = this.document.defaultView;

            this.documentResizeListener = this.renderer.listen(window, 'resize', this.onWindowResize.bind(this));
        }
    }

    unbindDocumentResizeListener() {
        if (this.documentResizeListener) {
            this.documentResizeListener();
            this.documentResizeListener = null;
        }
    }

    bindScrollListener() {
        if (!this.scrollHandler && isPlatformBrowser(this.platformId)) {
            this.scrollHandler = new ConnectedOverlayScrollHandler(this.target, () => {
                if (this.visible()) {
                    this.hide();
                }
            });
        }

        this.scrollHandler?.bindScrollListener();
    }

    unbindScrollListener() {
        if (this.scrollHandler) {
            this.scrollHandler.unbindScrollListener();
            this.scrollHandler = null;
        }
    }

    onOverlayHide() {
        this.unbindDocumentClickListener();
        this.unbindDocumentResizeListener();
        this.unbindScrollListener();
        this.preventDocumentDefault = false;

        if (!(this.cd as ViewRef).destroyed) {
            this.target = null;
        }

        if (this.container) {
            if (this.autoZIndex()) {
                ZIndexUtils.clear(this.container);
            }

            this.container = undefined;
        }
    }

    onDestroy() {
        if (this.popup()) {
            if (this.scrollHandler) {
                this.scrollHandler.destroy();
                this.scrollHandler = null;
            }

            if (this.container) {
                if (this.autoZIndex()) {
                    ZIndexUtils.clear(this.container);
                }

                this.container = undefined;
            }

            this.restoreOverlayAppend();
            this.onOverlayHide();
        }

        if (!this.popup()) {
            this.unbindDocumentClickListener();
        }
    }

    hasSubMenu(): boolean {
        return this.model()?.some((item) => item.items) ?? false;
    }

    getSubmenuKey(submenu: MenuItem, id: string): string {
        return submenu?.key != null ? String(submenu.key) : id;
    }

    isSubmenuToggleable(submenu: MenuItem, depth: number = 0): boolean {
        if (submenu.toggleable !== undefined) {
            return submenu.toggleable;
        }

        return depth > 0;
    }

    isSubmenuExpanded(submenu: MenuItem, depth: number = 0, id?: string): boolean {
        if (!this.isSubmenuToggleable(submenu, depth)) {
            return true;
        }

        if (id) {
            const key = this.getSubmenuKey(submenu, id);
            const expandedKeys = this.currentExpandedKeys();

            if (expandedKeys && key in expandedKeys) {
                return expandedKeys[key];
            }
        }

        return submenu.expanded === true;
    }

    toggleSubmenu(submenu: MenuItem, id: string, depth: number = 0) {
        const key = this.getSubmenuKey(submenu, id);
        const isExpanded = this.isSubmenuExpanded(submenu, depth, id);
        const next = { ...(this.currentExpandedKeys() || {}), [key]: !isExpanded };

        if (this.expandedKeys() !== undefined) {
            this.expandedKeys.set(next);
        } else {
            this.d_expandedKeys.set(next);
        }

        submenu.expanded = !isExpanded;
    }

    onItemLiClick(event: Event, item: MenuItem, id: string, depth: number) {
        if (item.items?.length && this.isSubmenuToggleable(item, depth)) {
            event.preventDefault();
        }
    }

    onItemLiMousedown(event: Event, item: MenuItem, depth: number) {
        if (item.items?.length && this.isSubmenuToggleable(item, depth)) {
            event.preventDefault();
        }
    }

    focusMenuList() {
        const list = this.listViewChild()?.nativeElement;

        if (list) focus(list);
    }

    isItemHidden(item: MenuItem): boolean {
        if (item.separator) {
            return item.visible === false || !!(item.items && item.items.some((subitem: MenuItem) => subitem.visible !== false));
        }

        return item.visible === false;
    }
}

@NgModule({
    imports: [Menu, SharedModule, SafeHtmlPipe],
    exports: [Menu, SharedModule, SafeHtmlPipe]
})
export class MenuModule {}
